from pathlib import Path
from html import escape as e
import json,re,runpy
root=Path(__file__).parent
runpy.run_path(str(root/'build-home.py'))
rows=[line.split('\t') for line in (root/'exercises.tsv').read_text().splitlines()]
assert len(rows)==33 and all(len(r)==11 for r in rows)
categories={'legs':('Legs','Ноги'),'posterior':('Posterior chain','Задняя цепь'),'chest':('Chest','Грудь'),'back':('Back','Спина'),'shoulders':('Shoulders','Плечи'),'arms':('Arms','Руки'),'core':('Core','Корпус')}
joints={'hip':('Hip','Тазобедренный сустав'),'knee':('Knee','Коленный сустав'),'ankle':('Ankle','Голеностопный сустав'),'shoulder':('Shoulder','Плечевой сустав'),'elbow':('Elbow','Локтевой сустав'),'trunk':('Trunk','Корпус')}
for lang in ['en','ru']:
 i=0 if lang=='en' else 1
 home=root/'dist'/lang/'index.html';s=home.read_text()
 # Keep the three original simulation cards at the top of the catalogue.
 s=s.replace('class="card"','class="card" data-group="legs" data-kind="original"',2)
 # Hip thrust is the third original card.
 pos=s.find('class="card"',s.find('data-kind="original"')+30)
 s=s.replace('class="card" href=', 'class="card" data-group="posterior" data-kind="original" href=')
 cards=''
 for n,r in enumerate(rows,4):
  id,group,en,ru,men,mru,joint,ten,tru,ben,bru=r
  name=(en,ru)[i];mus=(men,mru)[i];tip=(ten,tru)[i];bio=(ben,bru)[i];cat=categories[group][i]
  diagram=f'<svg viewBox="0 0 300 160" aria-hidden="true"><path d="M55 132H245" stroke="#292e35"/><path d="M95 115L150 80L210 105" fill="none" stroke="#d5dce4" stroke-width="9" stroke-linecap="round"/><circle cx="150" cy="80" r="11" fill="#090a0c" stroke="#47ff9e" stroke-width="3"/><path d="M210 105v35m-6-7 6 7 6-7" stroke="#ff47a8" fill="none" stroke-width="3"/><text x="22" y="27" fill="#8e969e" font-size="12">{e(joints[joint][i])}</text></svg>'
  cards+=f'<a class="card" data-group="{group}" data-kind="explorer" href="/{lang}/{id}.html"><div class="image schematic">{diagram}<span class="number">{n:02d}</span></div><div class="card-body"><span class="category">{e(cat)} · {"Mechanics explorer" if i==0 else "Разбор механики"}</span><h2>{e(name)}</h2><p>{e(mus)}</p><span class="card-cta">{"Explore exercise" if i==0 else "Разобрать упражнение"}<span class="arrow" aria-hidden="true">↗</span></span></div></a>'
  labels=(dict(title='Single-joint lever model',intro='Explore the external moment around the selected joint. The diagram isolates a rigid lever, not a full-body exercise animation.',tech='Technique cue',bio='What changes the mechanics?',muscles='Main muscles',joint='Model focus',angle='Lever angle from horizontal',force='Applied force',length='Lever length',direction='Force direction from horizontal',moment='External moment magnitude',arm='Perpendicular moment arm',play='Animate',pause='Pause',reset='Reset',note='Illustrative geometry only. The force acts at the end of the lever; bodyweight, other joints and internal muscle forces are omitted. Slider limits are model settings, not prescribed exercise ranges. The result is not muscle activation or an exercise-specific strength prediction.',back='All exercises') if i==0 else dict(title='Модель рычага одного сустава',intro='Изучите внешний момент относительно выбранного сустава. На схеме выделен жёсткий рычаг, а не полная анимация упражнения.',tech='Ориентир по технике',bio='Что меняет механику?',muscles='Основные мышцы',joint='Фокус модели',angle='Угол рычага от горизонтали',force='Приложенная сила',length='Длина рычага',direction='Направление силы от горизонтали',moment='Модуль внешнего момента',arm='Перпендикулярное плечо силы',play='Анимация',pause='Пауза',reset='Сбросить',note='Иллюстрация геометрии: сила приложена к концу рычага. Вес тела, другие суставы и внутренние силы мышц не учитываются. Пределы ползунков — настройки модели, а не рекомендуемая амплитуда упражнения. Результат не показывает активацию мышц и не прогнозирует силу в конкретном упражнении.',back='Все упражнения'))
  def slider(key,label,min,max,val,step,unit):return f'<label for="{key}">{label}<output id="{key}Out"></output></label><input id="{key}" type="range" min="{min}" max="{max}" value="{val}" step="{step}" data-unit="{unit}">'
  controls=slider('angle',labels['angle'],-90,90,30,1,'°')+slider('force',labels['force'],0,1000,100,10,'N')+slider('length',labels['length'],.1,1,.4,.01,'m')+slider('direction',labels['direction'],-180,180,-90,1,'°')
  nav=f'<nav class="languages"><a href="../en/{id}.html" {"aria-current=page" if i==0 else ""}>EN</a><a href="../ru/{id}.html" {"aria-current=page" if i==1 else ""}>RU</a></nav>'
  content=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(name)} · Cualigrafía</title><meta name="description" content="{e(bio)}"><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/explorer.css"></head><body><div class="wrap"><header><a href="./index.html">← {labels['back']}</a>{nav}</header><main><section class="intro"><div class="eyebrow">{e(cat)}</div><h1>{e(name)}</h1><p class="lead">{e(mus)}</p></section><div class="explorer-grid"><section class="model"><h2>{labels['title']}</h2><p>{labels['intro']}</p><svg id="model" viewBox="0 0 600 400" role="img" aria-label="{e(labels['title'])}"><defs><marker id="arrowhead" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#ff47a8"/></marker></defs><path d="M20 200H580M180 20V380" stroke="#242931" stroke-dasharray="4 7"/><path id="forceLine" stroke="#ff47a8" stroke-opacity=".3" stroke-width="2" stroke-dasharray="6 5"/><path id="armLine" stroke="#f6c915" stroke-width="3" stroke-dasharray="6 4"/><path id="lever" stroke="#d5dce4" stroke-width="14" stroke-linecap="round"/><circle cx="180" cy="200" r="13" fill="#101216" stroke="#47ff9e" stroke-width="4"/><circle id="end" r="8" fill="#d5dce4"/><path id="forceArrow" stroke="#ff47a8" stroke-width="4" marker-end="url(#arrowhead)"/></svg><div class="metrics"><div>{labels['moment']}<strong id="moment">—</strong></div><div>{labels['arm']}<strong id="arm">—</strong></div></div><p class="formula">|τ| = F · r · |sin(φ − θ)|</p></section><section class="settings"><p>{labels['joint']}: <strong>{e(joints[joint][i])}</strong></p>{controls}<div class="actions"><button id="play">{labels['play']}</button><button id="reset">{labels['reset']}</button></div></section></div><section class="explanation"><article><h2>{labels['tech']}</h2><p>{e(tip)}</p></article><article><h2>{labels['bio']}</h2><p>{e(bio)}</p></article></section><aside class="note"><span class="symbol">↳</span><p>{labels['note']}</p></aside></main><footer><span>{"Educational extension" if i==0 else "Учебное расширение каталога"}</span><a href="https://cualigrafia.com/">Cualigrafía</a></footer></div><script>window.EXPLORER={{id:{json.dumps(id)},lang:{json.dumps(lang)},play:{json.dumps(labels['play'])},pause:{json.dumps(labels['pause'])}}};</script><script src="../assets/explorer.js"></script></body></html>'''
  (root/'dist'/lang/f'{id}.html').write_text(content)
 filters=f'<div class="catalog-tools"><label>{"Find an exercise" if i==0 else "Найти упражнение"}<input type="search" id="search" placeholder="{"Name or muscle…" if i==0 else "Название или мышца…"}"></label><label>{"Muscle group" if i==0 else "Группа мышц"}<select id="group"><option value="all">{"All groups" if i==0 else "Все группы"}</option>'+''.join(f'<option value="{k}">{v[i]}</option>' for k,v in categories.items())+f'</select></label><label>{"Format" if i==0 else "Формат"}<select id="kind"><option value="all">{"All formats" if i==0 else "Все форматы"}</option><option value="original">{"Original simulator" if i==0 else "Исходный симулятор"}</option><option value="explorer">{"Mechanics explorer" if i==0 else "Разбор механики"}</option></select></label><p id="results" role="status"></p></div>'
 s=s.replace('<div class="cards">',filters+'<div class="cards">',1)
 s=s.replace('</div></section><aside',cards+'</div><p id="empty" hidden>'+('No exercises found. Try a different filter.' if i==0 else 'Упражнения не найдены. Измените фильтры.')+'</p></section><aside',1)
 s=s.replace('03 interactive simulators','36 exercises · 3 original simulators').replace('03 интерактивных симулятора','36 упражнений · 3 исходных симулятора')
 s=s.replace('</body>','<script src="../assets/catalog.js"></script></body>')
 home.write_text(s)
 if lang=='ru':(root/'dist/index.html').write_text(s.replace('src="../assets/catalog.js"','src="./assets/catalog.js"'))
print('Generated 33 new exercise pages per language; 36 total exercises.')
